+/** Marks a pattern segment that is exactly `**`. */
+const GLOBSTAR = Symbol("globstar");
+
+type Segment = typeof GLOBSTAR | RegExp;
+
+interface CompiledPattern {
+  /** The pattern exactly as it was given, including a leading `!`. */
+  raw: string;
+  negated: boolean;
+  segments: Segment[];
+}
+
+/** Compiles one path segment (no `/` inside) into an anchored regex. */
+function compileSegment(segment: string): RegExp {
+  let body = "";
+  let inStar = false;
+  for (const ch of segment) {
+    if (ch === "*") {
+      // A run of `*` (including `**` inside a longer segment) acts like one `*`.
+      if (!inStar) body += "[^/]*";
+      inStar = true;
+      continue;
+    }
+    inStar = false;
+    if (ch === "?") {
+      body += "[^/]";
+    } else {
+      body += ch.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
+    }
+  }
+  return new RegExp(`^${body}$`, "u");
+}
+
+function compilePattern(raw: string): CompiledPattern {
+  const negated = raw.startsWith("!");
+  const body = negated ? raw.slice(1) : raw;
+  const segments: Segment[] = body
+    .split("/")
+    .map((seg) => (seg === "**" ? GLOBSTAR : compileSegment(seg)));
+  return { raw, negated, segments };
+}
